require __DIR__.'/../app/bootstrap.php';require __DIR__.'/Seed.php';$c=require __DIR__.'/../config/example.php';$c['dsn']='sqlite::memory:';$c['db_user']='';$c['db_password']='';$db=new Db($c);Migration::run($db);Seed::run($db,$c,uid());$app=new App($db,$c);$service=new MessageLabels($app);$admin=new Admin($app);$r=$db->one("SELECT * FROM users WHERE id='test-researcher'");$a=$db->one("SELECT * FROM applications WHERE user_id='test-student-4'");$messages=$db->all('SELECT * FROM messages WHERE app_id=? ORDER BY seq',[$a['id']]);$mid=$messages[0]['id'];$aid=$messages[1]['id'];$n=0;
function studentCheck($ok,$name){global $n;demand((bool)$ok,$name);echo 'PASS STUDENT LABELS '.(++$n).' '.$name.PHP_EOL;}
