$aiDef=$admin->mutate($r,'definition',['family'=>'label','name'=>'AI açıkladı','body'=>['target_role'=>'assistant','description'=>'AI yanıtı açıklama sunar.']]);$defs=$db->all("SELECT id,name,body FROM definitions WHERE family='label'");$messages[0]['private_note']='NEVER TRANSMIT';$payload=MessageLabels::payload($messages,$defs,'user');
