studentCheck(!isset($payload['context_messages'])&&$payload['messages'][0]['context_before']===[],'first student message cannot use a subsequent AI response');
$third=['id'=>'synthetic-next','seq'=>3,'role'=>'user','content'=>'Başka bir yol söyle.','status'=>'completed'];$withPrior=MessageLabels::payload([...$messages,$third],$defs,'user');studentCheck(array_column($withPrior['messages'][1]['context_before'],'id')===[$mid,$aid],'a later student target retains only its own preceding conversation');
studentCheck(!array_key_exists('context_before',$withPrior['messages'][1]['context_before'][0]),'prior context stays flat without recursive targets');
studentCheck(!str_contains(js($payload),'NEVER TRANSMIT'),'context and target payloads omit private fields');
$wire=Ai::labelWirePayload($payload);studentCheck(!isset($wire['label_definitions'][0]['body'])&&isset($wire['label_definitions'][0]['description']),'wire retains full descriptions once without duplicate body text');
$examplePayload=$payload;$examplePayload['label_definitions'][0]['body']['description']='Tanım.\nDahil: “Terimi tanımla.”\nDışla: "Neden etkili?"';$examplePayload['label_definitions'][0]['body']['description']=str_replace('\\n',"\n",$examplePayload['label_definitions'][0]['body']['description']);$exampleWire=Ai::labelWirePayload($examplePayload);studentCheck($exampleWire['label_definitions'][0]['positive_examples']===['Terimi tanımla.']&&$exampleWire['label_definitions'][0]['negative_examples']===['Neden etkili?'],'current description examples are extracted with inclusion and exclusion kept distinct');
$examplePayload['label_definitions'][0]['body']['description']='Yeni tanım; örnek yok.';$exampleWire=Ai::labelWirePayload($examplePayload);studentCheck($exampleWire['label_definitions'][0]['positive_examples']===[]&&$exampleWire['label_definitions'][0]['negative_examples']===[],'editing the description removes old example hints');
$transport=Ai::labelTransport($payload);studentCheck($transport['payload']['messages'][0]['id']==='M1'&&$transport['payload']['label_definitions'][0]['id']==='L1','provider receives short message and label codes');$roundtrip=Ai::restoreLabelTransport(['labels'=>['M1'=>['L1']],'message_scope'=>['M1'=>'pedagogical']],$transport);studentCheck($roundtrip['labels'][$mid]===[$payload['label_definitions'][0]['id']]&&$roundtrip['message_scope'][$mid]==='pedagogical','transport codes restore exact persistent IDs and topic metadata');studentReject(fn()=>Ai::restoreLabelTransport(['labels'=>['M1'=>['L999']]],$transport),'unknown transport label code is rejected');
$schema=Ai::responseFormat($payload,true)['json_schema']['schema']['properties']['decisions'];$props=(array)$schema['properties'];studentCheck($schema['required']===[$mid]&&count((array)$props[$mid]['properties'])===8&&$props[$mid]['additionalProperties']===false,'schema requires a boolean decision for every eligible label');
$decisions=[];foreach($payload['label_definitions'] as $d)$decisions[$d['id']]=false;$positive=array_keys($decisions);$decisions[$positive[0]]=true;$decisions[$positive[1]]=true;$output=['message_scope'=>[$mid=>'pedagogical'],'decisions'=>[$mid=>$decisions]];$map=Ai::labelDecisions($output,$payload);
studentCheck($map['labels'][$mid]===array_slice($positive,0,2),'multiple true decisions produce a unique label set');
$allFalse=array_fill_keys($positive,false);studentCheck(Ai::labelDecisions(['message_scope'=>[$mid=>'pedagogical'],'decisions'=>[$mid=>$allFalse]],$payload)['labels'][$mid]===[],'all false decisions preserve explicit no-match');
$bad=$output;unset($bad['decisions'][$mid][$positive[0]]);studentReject(fn()=>Ai::labelDecisions($bad,$payload),'omitted label decision is rejected');
$bad=$output;$bad['decisions'][$mid][$positive[0]]='false';studentReject(fn()=>Ai::labelDecisions($bad,$payload),'string false cannot become a selected label');
$bad=$output;$bad['decisions'][$mid][$aiDef['id']]=true;studentReject(fn()=>Ai::labelDecisions($bad,$payload),'foreign role decision is rejected');
$bad=$output;$bad['decisions'][$aid]=$decisions;studentReject(fn()=>Ai::labelDecisions($bad,$payload),'context-only message in decision output is rejected');
$outsideOutput=$output;$outsideOutput['message_scope'][$mid]='outside';studentCheck(Ai::labelDecisions($outsideOutput,$payload)['labels'][$mid]===[],'outside topic cannot select pedagogy-only labels even when model says true');
$custom=$payload;$custom['label_definitions'][0]['topic_scope']='outside';$custom['label_definitions'][0]['body']['topic_scope']='outside';$onlyFirst=$allFalse;$onlyFirst[$positive[0]]=true;studentCheck(Ai::labelDecisions(['message_scope'=>[$mid=>'outside'],'decisions'=>[$mid=>$onlyFirst]],$custom)['labels'][$mid]===[$positive[0]],'researcher can explicitly permit an outside-topic label');
$custom['label_definitions'][0]['topic_scope']='any';studentCheck(Ai::labelDecisions(['message_scope'=>[$mid=>'outside'],'decisions'=>[$mid=>$onlyFirst]],$custom)['labels'][$mid]===[$positive[0]],'both-topic label remains usable for outside messages');
$bad=$output;unset($bad['message_scope']);studentReject(fn()=>Ai::labelDecisions($bad,$payload),'missing topic decision is rejected');
$bad=$output;$bad['message_scope'][$mid]='unclear';studentReject(fn()=>Ai::labelDecisions($bad,$payload),'unsupported topic decision is rejected');
$rejected=false;try{$admin->mutate($r,'definition',['family'=>'label','name'=>'Missing scope','body'=>['target_role'=>'user','description'=>'Synthetic']]);}catch(Fault $e){$rejected=$e->getCode()===422;}studentCheck($rejected,'student label authoring requires explicit topic scope');
