$view=$app->view($r,$a['id']);$assistantState=MessageLabels::state($aid,$view['labels'],$view['label_reviews'],$view['label_batches']);studentCheck(!$assistantState['ai_known'],'unprocessed AI answer is not marked labeled or empty');
$assistant=$service->generate($r,$a['id'],'assistant');studentCheck(array_keys($assistant['labels'])===[$aid]&&$assistant['target_role']==='assistant','optional AI generation is a separate scope');
studentCheck($service->generate($r,$a['id'],'user')['batch_id']===$student['batch_id'],'student cache survives an intervening AI batch');
$admin->mutate($r,'labels',['message_id'=>$mid,'labels'=>[],'reason'=>'Synthetic empty researcher decision']);$view=$app->view($r,$a['id']);studentCheck(MessageLabels::state($mid,$view['labels'],$view['label_reviews'],$view['label_batches'])['effective']===[],'empty researcher decision remains authoritative');
