for($i=3;$i<=6;$i++){$m=$messages[0];unset($m['private_note']);$m['id']=uid();$m['seq']=$i;$db->insert('messages',$m);}
$chunked=$service->generate($r,$a['id'],'user');studentCheck(count($chunked['labels'])===5&&!array_key_exists($aid,$chunked['labels']),'multiple chunks preserve every student target without touching AI messages');
studentCheck(MessageLabels::inputHash($messages,$defs,'model','user')!==MessageLabels::inputHash($messages,$defs,'model','assistant'),'student and AI cache identities differ');
echo "TOTAL STUDENT LABELS $n checks passed; isolated SQLite/mock.\n";
